frappe.ui.form.on('Sales Invoice', {
    custom_sales_invoice_type: function(frm) {
        set_custom_naming_series(frm);
    },
    unit: function(frm) {
        set_custom_naming_series(frm);
    }
});

function set_custom_naming_series(frm) {
    // Only apply on new, unsaved documents
    if (!frm.is_new()) return;

    const unit = frm.doc.unit;
    const inv_type = frm.doc.custom_sales_invoice_type;

    if (!unit || !inv_type) return;

    // Map Unit to its code (Unit-1 -> 1, Unit-2 -> 2, Unit-6 -> 6)
    const unit_map = {
        'Unit-1': '1',
        'Unit-2': '2',
        'Unit-6': '6'
    };

    // Map Type to its code (Domestic -> 1, Export -> 2)
    const type_map = {
        'Domestic': '1',
        'Export': '2'
    };

    const unit_code = unit_map[unit];
    const type_code = type_map[inv_type];

    if (unit_code && type_code) {
        // Construct prefix: 26 + unit_code + type_code + .####
        const target_series = `26${unit_code}${type_code}.####`;

        // Check if the series is valid in the Naming Series options
        const current_options = (frm.fields_dict['naming_series'].df.options || '').split('\n');
        
        if (!current_options.includes(target_series)) {
            current_options.push(target_series);
            frm.set_df_property('naming_series', 'options', current_options.join('\n'));
        }

        frm.set_value('naming_series', target_series);
    }
}

frappe.ui.form.on('Purchase Order', {
    before_workflow_action: async function(frm) {
        
        if (frm.selected_workflow_action === 'Reject') {
            
            // 1. Instantly unfreeze the UI that the native workflow engine locked
            frappe.dom.unfreeze(); 

            return new Promise((resolve, reject) => {
                let dialog = frappe.prompt(
                    [
                        {
                            fieldname: 'reason',
                            label: __('Reason for Rejection'),
                            fieldtype: 'Small Text',
                            reqd: 1,
                            description: __('Please provide a detailed reason for rejecting this Purchase Order.')
                        }
                    ],
                    function(values) {
                        // 2. Re-apply the freeze to prevent duplicate user clicks
                        frappe.dom.freeze(__('Processing Rejection...'));
                        
                        // 3. Inject the captured value into the local UI state ONLY (do not save yet)
                        frm.set_value('custom_reason_for_rejection', values.reason)
                            .then(() => {
                                // 4. CRITICAL FIX: Bypass native continuation. Manually execute the backend 
                                // workflow API. This natively packages the locally updated frm.doc (with the reason) 
                                // and the action into a single server-side save and transition.
                                return frappe.xcall('frappe.model.workflow.apply_workflow', {
                                    doc: frm.doc,
                                    action: 'Reject'
                                });
                            })
                            .then((updated_doc) => {
                                // 5. The backend transaction succeeded. Update the local UI.
                                frappe.dom.unfreeze();
                                frappe.model.sync(updated_doc);
                                frm.refresh();
                                
                                frappe.show_alert({
                                    message: __('Purchase Order Rejected Successfully'), 
                                    indicator: 'green'
                                });
                                
                                // 6. ABORT NATIVE PROMISE: We already executed the workflow manually. 
                                // Rejecting this promise prevents the framework from running it a second time.
                                reject(); 
                            })
                            .catch((err) => {
                                // 7. Graceful error handling
                                frappe.dom.unfreeze();
                                frappe.msgprint({
                                    title: __('Error'),
                                    indicator: 'red',
                                    message: __('System failed to process the workflow rejection.')
                                });
                                reject(err);
                            });
                    },
                    __('Enter Reason for Rejection'),
                    __('Confirm Rejection')
                );

                // 8. Handle modal cancellation safely to unblock the UI
                dialog.$wrapper.on('hidden.bs.modal', function() {
                    frappe.dom.unfreeze();
                    reject(); 
                });
            });
        }
    }
});

frappe.ui.form.on('Material Request', {
    refresh: function(frm) {
        if (!frm.is_new() && frm.page.actions) {
            setup_mr_reject_action_override(frm);
        }
    }
});

function setup_mr_reject_action_override(frm) {
    setTimeout(() => {
        let reject_btn = frm.page.actions.find(`li:contains("Reject")`);

        if (reject_btn && reject_btn.length) {
            reject_btn.off('click').on('click', function(e) {
                e.preventDefault();
                e.stopImmediatePropagation();

                frappe.prompt([
                    {
                        fieldname: 'reason',
                        label: __('Reason for Rejection'),
                        fieldtype: 'Small Text',
                        reqd: 1
                    }
                ], function(values) {
                    frappe.call({
                        method: 'frappe.client.set_value',
                        args: {
                            doctype: frm.doc.doctype,
                            name: frm.doc.name,
                            fieldname: {
                                'custom_reason_for_rejection': values.reason
                            }
                        },
                        callback: function() {
                            frappe.xcall('frappe.model.workflow.apply_workflow', {
                                doc: frm.doc,
                                action: 'Reject'
                            }).then(() => {
                                frm.reload_doc();
                                frappe.msgprint(__('Material Request has been rejected with reason.'));
                            });
                        }
                    });
                }, __('Enter Reason for Rejection'), __('Reject MR'));
            });
        }
    }, 500);
}

frappe.ui.form.on('Stock Entry', {
    
    unit: function(frm) {
        sync_header_dimensions_to_items(frm, 'unit', frm.doc.unit);
    },

    
    cost_center: function(frm) {
        sync_header_dimensions_to_items(frm, 'cost_center', frm.doc.cost_center);
    }
});

frappe.ui.form.on('Stock Entry Detail', {
    
    items_add: function(frm, cdt, cdn) {
        if (frm.doc.unit) {
            frappe.model.set_value(cdt, cdn, 'unit', frm.doc.unit);
        }
        if (frm.doc.cost_center) {
            frappe.model.set_value(cdt, cdn, 'cost_center', frm.doc.cost_center);
        }
    }
});


function sync_header_dimensions_to_items(frm, fieldname, value) {
    if (!frm.doc.items || frm.doc.items.length === 0) return;

    frm.doc.items.forEach(row => {
        frappe.model.set_value(row.doctype, row.name, fieldname, value);
    });

    frm.refresh_field('items');
}

frappe.ui.form.on('Delivery Note', {

    unit: function(frm) {
        sync_field_to_tables(frm, 'unit', frm.doc.unit);
    },

    cost_center: function(frm) {
        sync_field_to_tables(frm, 'cost_center', frm.doc.cost_center);
    }
});

frappe.ui.form.on('Delivery Note Item', {
    items_add: function(frm, cdt, cdn) {
        set_row_dimensions(frm, cdt, cdn);
    }
});


frappe.ui.form.on('Sales Taxes and Charges', {
    taxes_add: function(frm, cdt, cdn) {
        set_row_dimensions(frm, cdt, cdn);
    }
});


function sync_field_to_tables(frm, fieldname, value) {
    // Items table update
    if (frm.doc.items && frm.doc.items.length > 0) {
        frm.doc.items.forEach(row => {
            frappe.model.set_value(row.doctype, row.name, fieldname, value);
        });
        frm.refresh_field('items');
    }

    // Taxes table update
    if (frm.doc.taxes && frm.doc.taxes.length > 0) {
        frm.doc.taxes.forEach(row => {
            frappe.model.set_value(row.doctype, row.name, fieldname, value);
        });
        frm.refresh_field('taxes');
    }
}


function set_row_dimensions(frm, cdt, cdn) {
    if (frm.doc.unit) {
        frappe.model.set_value(cdt, cdn, 'unit', frm.doc.unit);
    }
    if (frm.doc.cost_center) {
        frappe.model.set_value(cdt, cdn, 'cost_center', frm.doc.cost_center);
    }
}

frappe.ui.form.on('Sales Order', {
    
    cost_center: function(frm) {
        sync_all_dimensions(frm);
    },


    unit: function(frm) {
        sync_all_dimensions(frm);
    },


    taxes_and_charges: function(frm) {
        setTimeout(() => {
            sync_all_dimensions(frm);
        }, 800);
    },


    validate: function(frm) {
        sync_all_dimensions(frm);
    }
});


frappe.ui.form.on('Sales Taxes and Charges', {
