frappe.ui.form.on('Sales Order Item', {
    items_add: function(frm, cdt, cdn) {
        if (frm.doc.cost_center) {
            frappe.model.set_value(cdt, cdn, 'cost_center', frm.doc.cost_center);
        }
        if (frm.doc.unit) {
            frappe.model.set_value(cdt, cdn, 'unit', frm.doc.unit);
        }
    }
});

function sync_all_dimensions(frm) {
    // 1. Sync to Items Table
    if (frm.doc.items && frm.doc.items.length > 0) {
        frm.doc.items.forEach(row => {
            if (frm.doc.cost_center && row.cost_center !== frm.doc.cost_center) {
                frappe.model.set_value(row.doctype, row.name, 'cost_center', frm.doc.cost_center);
            }
            if (frm.doc.unit && row.unit !== frm.doc.unit) {
                frappe.model.set_value(row.doctype, row.name, 'unit', frm.doc.unit);
            }
        });
        frm.refresh_field('items');
    }

    // 2. Sync to Taxes Table
    if (frm.doc.taxes && frm.doc.taxes.length > 0) {
        frm.doc.taxes.forEach(row => {
            if (frm.doc.cost_center && row.cost_center !== frm.doc.cost_center) {
                frappe.model.set_value(row.doctype, row.name, 'cost_center', frm.doc.cost_center);
            }
            if (frm.doc.unit && row.unit !== frm.doc.unit) {
                frappe.model.set_value(row.doctype, row.name, 'unit', frm.doc.unit);
            }
        });
        frm.refresh_field('taxes');
    }
}

frappe.ui.form.on('Purchase Receipt', {
    refresh: function(frm) {
        // 1. Verify the receipt has items and a linked PO
        if (frm.doc.items && frm.doc.items.length > 0 && frm.doc.items[0].purchase_order) {
            
            // 2. Fetch the custom PO type from the database
            frappe.db.get_value('Purchase Order', frm.doc.items[0].purchase_order, 'custom_purchase_order_type')
                .then(r => {
                    // 3. Use .includes() to prevent formatting or space character mismatches
                    if (r && r.message && r.message.custom_purchase_order_type && r.message.custom_purchase_order_type.includes('Service PO')) {
                        
                        // 4. Inject a custom print button specifically for services
                        frm.add_custom_button(__('Print SRN'), function() {
                            frm.meta.default_print_format = 'Service Receipt Note';
                            frm.print_doc();
                        });
                        
                        // 5. Highlight the button to draw the user's attention
                        frm.change_custom_button_type('Print SRN', null, 'primary');
                    }
                });
        }
    }
});

frappe.ui.form.on('Purchase Order', {
    refresh: function(frm) {
        
        // 1. Filter the HEADER Cost Center dropdown
        frm.set_query("cost_center", function(doc) {
            if (doc.unit) {
                let match = doc.unit.match(/\d+/);
                if (match) {
                    return { filters: { 'name': ['like', '_' + match[0] + '%'] } };
                }
            }
            return {};
        });
        

        // 2. Filter the ITEMS TABLE Cost Center dropdown
        frm.set_query("cost_center", "items", function(doc, cdt, cdn) {
            let row = locals[cdt][cdn];
            if (row.unit) {
                let match = row.unit.match(/\d+/);
                if (match) {
                    return { filters: { 'name': ['like', '_' + match[0] + '%'] } };
                }
            }
            return {};
        });
    },
    
    // 3. Auto-populate Unit when HEADER Cost Center changes
    cost_center: function(frm) {
        if (frm.doc.cost_center) {
            // Extract the 2nd character (Index 1) from the Cost Center ID
            let unit_char = frm.doc.cost_center.substring(1, 2); 
            if (['1', '2', '6'].includes(unit_char)) {
                let target_unit = 'Unit-' + unit_char;
                if (frm.doc.unit !== target_unit) {
                    frm.set_value('unit', target_unit);
                }
            } else {
                if (frm.doc.unit) { frm.set_value('unit', ''); }
            }
        }
    },
    
    
    
    
});




