function check_and_apply_commission_rules(frm) {
    let items_total = 0.0;
    let line_item_has_rate = false;

    
    (frm.doc.items || []).forEach(row => {
        let line_rate = flt(row.custom_commission_rate__value);
        let line_amt = flt(row.custom_commission_amount);

        if (line_rate > 0 || line_amt > 0) {
            line_item_has_rate = true;
            items_total += line_amt;
        }
    });

    if (line_item_has_rate) {
        
        frm.set_value('commission_rate', 0);
        frm.set_df_property('commission_rate', 'read_only', 1);
        frm.refresh_field('commission_rate');

        
        frm.set_value('total_commission', items_total);
    } else {
        
        frm.set_df_property('commission_rate', 'read_only', 0);
        frm.refresh_field('commission_rate');

        
        if (flt(frm.doc.commission_rate) > 0) {
            let header_calc = (flt(frm.doc.net_total) * flt(frm.doc.commission_rate)) / 100.0;
            frm.set_value('total_commission', header_calc);
        }
    }

    if (flt(frm.doc.total_commission) > 0) {
        frm.set_value('amount_eligible_for_commission', flt(frm.doc.net_total));
    }
}

