// Client Script: MR Rejection Prompt
// Intercepts Workflow actions, explicitly destroys modals, and writes directly to the backend Database

frappe.ui.form.on('Material Request', {
    
    // 1. Force the field to be visually Read-Only on the form UI
    refresh: function(frm) {
        frm.set_df_property('custom_reason_for_rejection', 'read_only', 1);
    },

    // 2. Hook into the workflow action
    before_workflow_action: async (frm) => {
        if (frm.selected_workflow_action === 'Reject') {
            
            return new Promise((resolve, reject) => {
                
                // Unfreeze the DOM so the modal is interactive
                frappe.dom.unfreeze();

                let d = new frappe.ui.Dialog({
                    title: 'Reason for Rejection',
                    fields: [
                        {
                            label: 'Please enter the Reason for Rejection',
                            fieldname: 'rejection_reason',
                            fieldtype: 'Small Text',
                            reqd: 1, // Mandatory field
                            default: frm.doc.custom_reason_for_rejection || '' 
                        }
                    ],
                    primary_action_label: 'Submit Rejection',
                    
                    primary_action(values) {
                        
                        // Forcefully destroy and hide the dialog box immediately
                        d.hide();
                        
                        // Briefly apply a native freeze mask so the user knows it is processing
                        frappe.dom.freeze('Saving Reason...');
                        
                        // CRITICAL FIX: Bypass the UI and Model entirely.
                        // Execute a direct, asynchronous database write to the Frappe backend.
                        frappe.db.set_value('Material Request', frm.doc.name, 'custom_reason_for_rejection', values.rejection_reason)
                        .then((r) => {
                            
                            // The database has explicitly confirmed the new text is saved.
                            // Resolve the promise. The workflow engine will now execute the state 
                            // transition, pull the fresh data from the database, and reload the screen.
                            resolve(); 
                        });
                    }
                });

                // Render the dialog to the user
                d.show();
            });
        }
    }
});

frappe.ui.form.on('Material Request', {
    validate: function(frm) {
        // Initialize a JavaScript Set to hold unique unit values
        let unique_units = new Set();

        // Ensure the items table actually has rows before looping
        if (frm.doc.items && frm.doc.items.length > 0) {
            
            // Loop through each row in the child table
            frm.doc.items.forEach(function(row) {
                // Check if the target field is populated on this row
                
                if (row.unit) {
                    unique_units.add(row.unit);
                }
            });

            // If the Set contains more than 1 item, we have mixed units
            if (unique_units.size > 1) {
                
                // Convert the Set to a readable comma-separated string
                let mixed_units_list = Array.from(unique_units).join(", ");
                
                // Display a formatted error message to the user
                frappe.msgprint({
                    title: __('Data Integrity Error'),
                    indicator: 'red',
                    message: __('All items in a single Material Request must belong to the exact same Unit. You have mixed items for: <b>{0}</b>. Please split these into separate Material Requests.', [mixed_units_list])
                });
                
                // CRITICAL: This command halts the save process on the client side
                frappe.validated = false; 
            }
        }
    }
});

