function render_all_pending_indicators(frm) {
    if (!frm.doc.items || frm.doc.items.length === 0) return;

    frm.doc.items.forEach(row => {
        if (!row.item_code) return;

        frappe.call({
            method: 'get_pending_po_details',
            args: {
                item_code: row.item_code,
                current_po: frm.doc.name || ''
            },
            callback: function(r) {
                if (r.message && r.message.length > 0) {
                    let total_pending = 0;
                    r.message.forEach(d => {
                        total_pending += flt(d.pending_qty);
                    });
                    render_price_intelligence_badge(row.name, row.item_code, total_pending, row.uom, r.message);
                }
            }
        });
    });
}

