function calculate_totals(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    let qty = flt(row.returning_qty);
    let rate = flt(row.unit_rate);
    frappe.model.set_value(cdt, cdn, 'total_amount', qty * rate);
    update_grand_total(frm);
}

function update_grand_total(frm) {
    let grand_total = 0;
    (frm.doc.packaging_items || []).forEach(d => {
        grand_total += flt(d.total_amount);
    });

    frm.set_value('consignment_total_value', grand_total);

    if (grand_total > 50000) {
        frm.set_value('ewaybill_required', 1);
        frappe.show_alert({
            message: __('Consignment total value is ₹{0}. e-Waybill is mandatory!', [format_currency(grand_total)]),
            indicator: 'orange'
        }, 5);
    } else {
        frm.set_value('ewaybill_required', 0);
    }
}

