function get_material_request_unit(frm) {
    const items = frm.doc.items || [];
    const row_with_unit = items.find(row => row.unit);
    return row_with_unit ? String(row_with_unit.unit).trim() : "";
}

function validate_same_unit_in_all_items(frm) {
    const items_with_unit = (frm.doc.items || []).filter(row => row.unit);

    if (!items_with_unit.length) {
        return;
    }

    const first_unit = String(items_with_unit[0].unit).trim();

    const different_unit_row = items_with_unit.find(row => {
        return String(row.unit).trim() !== first_unit;
    });

    if (different_unit_row) {
        frappe.throw(
            __(
                "All Material Request Item rows must have the same Unit. Row {0} contains Unit {1}, while the first selected Unit is {2}.",
                [
                    different_unit_row.idx,
                    different_unit_row.unit,
                    first_unit
                ]
            )
        );
    }
}

function set_material_request_naming_series(frm) {
    if (!frm.is_new()) {
        return;
    }

    const department = frm.doc.custom_department;
    const unit = get_material_request_unit(frm);

    if (!department || !unit) {
        frm.set_value("naming_series", "");
        return;
    }

    const department_code = String(department)
        .split(" - ")[0]
        .trim()
        .toUpperCase();

    const allowed_department_codes = [
        "ACC",
        "ADM",
        "ARD",
        "COM",
        "COS",
        "DMK",
        "EHS",
        "EST",
        "ENG",
        "ETP",
        "EXP",
        "FIN",
        "FRD",
        "IMK",
        "IT",
        "MIS",
        "PNA",
        "PDL",
        "PWP",
        "PRD",
        "PUR",
        "QA",
        "QCM",
        "QC",
        "RND",
        "REG",
        "CRA",
        "SEC",
        "SRP-A",
        "SGY",
        "SCM",
        "WH",
        "FARD",
        "HR",
        // Sterile Departments
        "STRA",
        "STRB",
        "STRC",
        "STRD",
        "STRE",
        "SRP1",
        "SRP2",
        // Oral Departments
        "ORA",
        "ORB",
        "ORC",
        "ORD",
        "ORE",
        "ORF",
        "ORG",
        "ORH"
    ];

    if (!allowed_department_codes.includes(department_code)) {
        frm.set_value("naming_series", "");

        frappe.msgprint({
            title: __("Department Code Missing"),
            message: __(
                "Department code {0} is not configured for Material Request naming.",
                [department_code]
            ),
            indicator: "orange"
        });

        return;
    }

    /*
     * Flexible Unit matching:
     * Extracts the digit (1, 2, or 6) from formats like:
     * "Unit-1", "Unit -1", "Unit-2", "Unit Unit-2", "Unit-6", etc.
     */
    let unit_code = "";
    const clean_unit = String(unit).trim().toUpperCase();

    if (/\b(?:UNIT[- ]*)?1\b/.test(clean_unit) || clean_unit.endsWith("1")) {
        unit_code = "U1";
    } else if (/\b(?:UNIT[- ]*)?2\b/.test(clean_unit) || clean_unit.endsWith("2")) {
        unit_code = "U2";
    } else if (/\b(?:UNIT[- ]*)?6\b/.test(clean_unit) || clean_unit.endsWith("6")) {
        unit_code = "U6";
    }

    if (!unit_code) {
        frm.set_value("naming_series", "");

        frappe.msgprint({
            title: __("Unit Code Missing"),
            message: __(
                "Unit {0} is not configured. Allowed values are Unit-1, Unit-2 and Unit-6.",
                [unit]
            ),
            indicator: "orange"
        });

        return;
    }

    const series = `${department_code}/${unit_code}/.####./.FY.`;

    const naming_series_field = frm.fields_dict.naming_series;

    if (naming_series_field) {
        const options = String(
            naming_series_field.df.options || ""
        )
            .split("\n")
            .map(value => value.trim())
            .filter(Boolean);

        if (!options.includes(series)) {
            options.push(series);

            frm.set_df_property(
                "naming_series",
                "options",
                options.join("\n")
            );
        }
    }

    frm.set_value("naming_series", series);
    frm.refresh_field("naming_series");
}

