frappe.ui.form.on('Bank Statement Import', {

    update_primary_action: function(frm) {
        if (frm.is_dirty()) { frm.enable_save(); return; }
        frm.disable_save();
        if (frm.doc.status !== 'Success') {
            frm.page.set_primary_action(__('Auto Map & Import'), function () { frm.events.run_auto_map(frm); });
        }
    },

    refresh: function(frm) {
        frm.add_custom_button(__('Auto Map & Import'), function () { frm.events.run_auto_map(frm); }, __('Actions'));
    },

    run_auto_map: function(frm) {
        if (!frm.doc.import_file) {
            frappe.msgprint({title: __('No File'), message: __('Please attach the bank statement .xlsx file using the Import File field, then save.'), indicator: 'red'});
            return;
        }
        frappe.show_progress(__('Importing...'), 0, 100, __('Processing bank statement sheets...'));
        frappe.call({
            method: 'vrindha_customisations.bank_statement.import_bank_statement',
            args: { docname: frm.doc.name },
            callback: function(r) {
                frappe.hide_progress();
                if (!r.message) return;
                var m            = r.message;
                var created      = m.created      || 0;
                var skipped      = m.skipped      || 0;
                var errs         = m.errors        || [];
                var skipped_rows = m.skipped_rows  || [];
                var color = created > 0 ? 'green' : 'orange';

                var detail = '<b>' + created + '</b> Bank Transaction(s) created, <b>' + skipped + '</b> skipped.';

                if (errs.length) {
                    detail += '<br><br><b>Errors:</b><ul>' +
                        errs.slice(0, 10).map(function(e){ return '<li>' + e + '</li>'; }).join('') + '</ul>';
                }

                if (skipped_rows.length) {
                    detail += '<br><b>Skipped rows (' + skipped_rows.length + '):</b><ul>' +
                        skipped_rows.slice(0, 10).map(function(e){ return '<li>' + e + '</li>'; }).join('');
                    if (skipped_rows.length > 10) detail += '<li>... and ' + (skipped_rows.length - 10) + ' more</li>';
                    detail += '</ul>';
                    detail += '<br><a id="download-skipped" href="#" style="font-weight:bold">&#11015; Download all skipped rows as CSV</a>';
                }

                frappe.msgprint({ title: __('Import Complete'), message: detail, indicator: color });

                if (skipped_rows.length) {
                    setTimeout(function() {
                        var el = document.getElementById('download-skipped');
                        if (!el) return;
                        el.addEventListener('click', function(e) {
                            e.preventDefault();
                            var header = 'Date,Reason,Description,Reference,Deposit,Withdrawal,Bank Account';
                            var lines = skipped_rows.map(function(row) {
                                var parts = row.split(' | ');
                                return parts.map(function(p) {
                                    return '"' + (p || '').replace(/"/g, '""') + '"';
                                }).join(',');
                            });
                            var csv  = header + '\n' + lines.join('\n');
                            var blob = new Blob([csv], {type: 'text/csv'});
                            var url  = URL.createObjectURL(blob);
                            var a    = document.createElement('a');
                            a.href     = url;
                            a.download = 'skipped_bank_transactions.csv';
                            a.click();
                            URL.revokeObjectURL(url);
                        });
                    }, 300);
                }

                frm.reload_doc();
            },
            error: function() {
                frappe.hide_progress();
                frappe.msgprint({ title: __('Import Failed'), message: __('Check bank account setup and try again.'), indicator: 'red' });
            }
        });
    }
});

