frappe.ui.form.on('Purchase Invoice', {
    custom_bill_of_lading_date_(frm) {
        calculate_due_date_from_bl(frm);
    },

    payment_terms_template(frm) {
        setTimeout(() => {
            calculate_due_date_from_bl(frm);
        }, 800);
    },

    posting_date(frm) {
        setTimeout(() => {
            calculate_due_date_from_bl(frm);
        }, 800);
    },

    refresh(frm) {
        calculate_due_date_from_bl(frm);
    },

    validate(frm) {
        calculate_due_date_from_bl(frm);
    }
});

function calculate_due_date_from_bl(frm) {
    if (!frm.doc.custom_bill_of_lading_date_ || !frm.doc.payment_terms_template) {
        return;
    }

    frappe.db.get_doc("Payment Terms Template", frm.doc.payment_terms_template)
        .then(template => {
            if (!template.terms || template.terms.length === 0) return;

            let max_due_date = null;

            template.terms.forEach(term => {
                let credit_days = term.credit_days || 0;
                let due_date = frappe.datetime.add_days(
                    frm.doc.custom_bill_of_lading_date_,
                    credit_days
                );

                frm.doc.payment_schedule.forEach(row => {
                    if (row.payment_term === term.payment_term) {
                        row.due_date = due_date;
                    }
                });

                if (!max_due_date || due_date > max_due_date) {
                    max_due_date = due_date;
                }
            });

            frm.set_value("due_date", max_due_date);
            frm.refresh_field("payment_schedule");
        });
}

frappe.ui.form.on("Item", {
    item_group: function(frm) {
        if (!frm.doc.item_group) return;

        let item_group_name = frm.doc.item_group.trim().toLowerCase();

        let series_map = {
            "raw material": { start: 1000000, end: 1099999 },
            "semi finished goods": { start: 1600000, end: 1699999 },
            "semi finished good": { start: 1600000, end: 1699999 },
            "finished goods": { start: 2000000, end: 2099999 },
            "finished good": { start: 2000000, end: 2099999 }
        };

        if (!series_map[item_group_name]) {
            frm.set_value("custom_item_code_series", "");
            frm.set_value("item_code", "");
            return;
        }

        let start_no = series_map[item_group_name].start;
        let end_no = series_map[item_group_name].end;

        frm.set_value("custom_item_code_series", start_no.toString());

        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Item",
                fields: ["item_code"],
                limit_page_length: 5000
            },
            callback: function(r) {
                let items = r.message || [];
                let latest_code = start_no - 1;

                items.forEach(function(item) {
                    let item_code = item.item_code ? item.item_code.toString().trim() : "";

                    if (/^\d+$/.test(item_code)) {
                        let code = parseInt(item_code);

                        if (code >= start_no && code <= end_no && code > latest_code) {
                            latest_code = code;
                        }
                    }
                });

                let next_code = latest_code + 1;

                if (next_code > end_no) {
                    frappe.msgprint("Item Code series completed for " + frm.doc.item_group);
                    return;
                }

                frm.set_value("item_code", next_code.toString());
            }
        });
    }
});

